<script setup lang="ts">
import { Building2, Check, ChevronDown, Mail, Plus, ShieldCheck, SlidersHorizontal, UserPlus, Users, X } from '@lucide/vue'
import { computed, onMounted, reactive, ref } from 'vue'
import api from '../api'

const emit = defineEmits<{ close: [] }>()
const loading=ref(true),saving=ref(false),error=ref(''),success=ref(''),roleOpen=ref(false)
const members=ref<any[]>([]),invitations=ref<any[]>([]),roles=ref<any[]>([]),branches=ref<any[]>([]),permissionOptions=ref<string[]>([])
const form=reactive({name:'',email:'',role_id:0,branches:[] as string[]})
const roleForm=reactive({name:'',permissions:['view_students'] as string[]})
const activeCount=computed(()=>members.value.filter(member=>member.status==='active').length)
const permissionLabel=(permission:string)=>permission.split('_').map(word=>word[0].toUpperCase()+word.slice(1)).join(' ')

async function load(){loading.value=true;try{const {data}=await api.get('/team');members.value=data.members.map((member:any)=>({...member,permissionOpen:false}));invitations.value=data.invitations;roles.value=data.roles.filter((role:any)=>role.key!=='owner');branches.value=data.branches;permissionOptions.value=data.permission_options;if(!form.role_id&&roles.value.length)form.role_id=roles.value[0].id;if(!form.branches.length&&branches.value.length)form.branches=[branches.value[0].public_id]}catch(e:any){error.value=e.response?.data?.message||'Unable to load staff access.'}finally{loading.value=false}}
async function invite(){saving.value=true;error.value='';success.value='';try{const {data}=await api.post('/team/invitations',form);success.value=data.member?`${data.member.user.name} was added to your team.`:`Invitation sent to ${data.invitation.email}.`;Object.assign(form,{name:'',email:'',role_id:roles.value[0]?.id||0,branches:branches.value[0]?[branches.value[0].public_id]:[]});await load()}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Unable to add this staff member.']}).flat().join(' ')}finally{saving.value=false}}
async function saveMember(member:any){member.saving=true;error.value='';success.value='';try{const {data}=await api.patch(`/team/members/${member.id}`,{role_id:member.role.id,status:member.status,branches:member.branches.map((branch:any)=>branch.public_id),permissions_allow:member.permission_overrides.allow,permissions_deny:member.permission_overrides.deny});const open=member.permissionOpen;Object.assign(member,data.member,{permissionOpen:open});success.value=`${member.user.name}'s access was updated.`}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Unable to update access.']}).flat().join(' ');await load()}finally{member.saving=false}}
function toggleMemberBranch(member:any,id:string){const index=member.branches.findIndex((branch:any)=>branch.public_id===id);if(index>=0)member.branches.splice(index,1);else{const branch=branches.value.find(item=>item.public_id===id);if(branch)member.branches.push(branch)}}
function cyclePermission(member:any,permission:string){const allow=member.permission_overrides.allow as string[];const deny=member.permission_overrides.deny as string[];const allowed=allow.indexOf(permission);const denied=deny.indexOf(permission);if(allowed>=0){allow.splice(allowed,1);deny.push(permission)}else if(denied>=0)deny.splice(denied,1);else allow.push(permission)}
function permissionState(member:any,permission:string){if(member.permission_overrides.allow.includes(permission))return'allow';if(member.permission_overrides.deny.includes(permission))return'deny';return'inherit'}
async function revoke(invitation:any){error.value='';try{await api.delete(`/team/invitations/${invitation.id}`);invitations.value=invitations.value.filter(item=>item.id!==invitation.id);success.value=`Invitation for ${invitation.email} was revoked.`}catch(e:any){error.value=e.response?.data?.message||'Unable to revoke this invitation.'}}
async function createRole(){saving.value=true;error.value='';try{await api.post('/team/roles',roleForm);success.value=`${roleForm.name} role created.`;roleForm.name='';roleForm.permissions=['view_students'];roleOpen.value=false;await load()}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Unable to create this role.']}).flat().join(' ')}finally{saving.value=false}}
onMounted(load)
</script>

<template><div class="modal-backdrop team-backdrop" @click.self="emit('close')"><section class="team-modal" role="dialog" aria-modal="true" aria-labelledby="team-title">
  <header class="team-modal-head"><div><span class="modal-icon"><Users/></span><span><small>PEOPLE & PERMISSIONS</small><h2 id="team-title">Staff and centre access</h2><p>Invite your team, choose roles, centre access and precise permission exceptions.</p></span></div><button @click="emit('close')"><X/></button></header>
  <div v-if="error" class="form-error team-alert">{{error}}<button @click="error=''">×</button></div><div v-if="success" class="team-success-alert"><Check/>{{success}}<button @click="success=''">×</button></div>
  <div v-if="loading" class="team-modal-loading"><span></span>Loading your team…</div><template v-else>
    <section class="team-invite-card"><div class="team-card-title"><span><UserPlus/></span><div><small>ADD STAFF MEMBER</small><b>Invite someone to your academy</b><p>Existing users are added immediately. Everyone else receives a secure seven-day invitation.</p></div><button class="role-builder-link" @click="roleOpen=!roleOpen"><ShieldCheck/>{{roleOpen?'Close role builder':'Create custom role'}}</button></div>
      <form v-if="roleOpen" class="role-builder" @submit.prevent="createRole"><label>Role name<input v-model="roleForm.name" required placeholder="Exam coordinator"></label><div><small>PERMISSIONS</small><label v-for="permission in permissionOptions" :key="permission" class="permission-chip"><input v-model="roleForm.permissions" type="checkbox" :value="permission"><span><Check/>{{permissionLabel(permission)}}</span></label></div><button class="button secondary" :disabled="saving"><Plus/>Save custom role</button></form>
      <form class="staff-invite-form" @submit.prevent="invite"><label>Full name<input v-model="form.name" required placeholder="Nour Ahmed"></label><label>Email address<input v-model="form.email" type="email" required placeholder="nour@academy.com"></label><label>Role<select v-model.number="form.role_id" required><option v-for="role in roles" :key="role.id" :value="role.id">{{role.name}}</option></select></label><fieldset><legend>Centre access</legend><label v-for="branch in branches" :key="branch.public_id"><input v-model="form.branches" type="checkbox" :value="branch.public_id"><span><Building2/>{{branch.name_en||branch.name_ar}}</span></label></fieldset><button class="button primary" :disabled="saving||!form.branches.length"><Mail/>{{saving?'Sending…':'Add or invite staff'}}</button></form>
    </section>
    <section class="team-directory"><div class="team-directory-head"><div><small>TEAM DIRECTORY</small><h3>{{activeCount}} active {{activeCount===1?'member':'members'}}</h3></div><span>Role permissions are the baseline; exceptions apply only to one person.</span></div>
      <div class="member-list"><article v-for="member in members" :key="member.id" class="member-row" :class="{expanded:member.permissionOpen}"><div class="member-person"><span>{{member.user.name.split(' ').map((name:string)=>name[0]).join('').slice(0,2)}}</span><div><b>{{member.user.name}}</b><small>{{member.user.email}}</small></div><em v-if="member.role?.key==='owner'">Owner</em></div><div class="member-controls"><label>Role<select v-model.number="member.role.id" :disabled="member.role?.key==='owner'"><option v-if="member.role?.key==='owner'" :value="member.role.id">Owner</option><option v-for="role in roles" v-else :key="role.id" :value="role.id">{{role.name}}</option></select></label><label>Status<select v-model="member.status" :disabled="member.role?.key==='owner'"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="member-branches"><small>CENTRES</small><label v-for="branch in branches" :key="branch.public_id" :class="{checked:member.branches.some((assigned:any)=>assigned.public_id===branch.public_id)}"><input type="checkbox" :checked="member.branches.some((assigned:any)=>assigned.public_id===branch.public_id)" :disabled="member.role?.key==='owner'" @change="toggleMemberBranch(member,branch.public_id)"><Check/>{{branch.name_en||branch.name_ar}}</label></div><button v-if="member.role?.key!=='owner'" class="permission-toggle" :class="{active:member.permissionOpen}" @click="member.permissionOpen=!member.permissionOpen"><SlidersHorizontal/><span>Exceptions</span><ChevronDown/></button><button v-if="member.role?.key!=='owner'" class="button secondary member-save" :disabled="member.saving||!member.branches.length" @click="saveMember(member)">{{member.saving?'Saving…':'Save access'}}</button></div>
        <div v-if="member.permissionOpen&&member.role?.key!=='owner'" class="permission-overrides"><div><b>Permission exceptions</b><p>Click once to allow, twice to deny, and a third time to inherit from the role.</p></div><div class="override-legend"><span class="allow">Allow</span><span class="deny">Deny</span><span>Inherit</span></div><div class="override-grid"><button v-for="permission in permissionOptions" :key="permission" :class="permissionState(member,permission)" @click="cyclePermission(member,permission)"><i></i>{{permissionLabel(permission)}}<small>{{permissionState(member,permission)}}</small></button></div></div>
      </article></div>
      <div v-if="invitations.length" class="pending-invites"><small>PENDING INVITATIONS</small><article v-for="invitation in invitations" :key="invitation.id"><span><Mail/></span><div><b>{{invitation.name}}</b><small>{{invitation.email}} · {{invitation.role.name}}</small></div><em :class="invitation.status">{{invitation.status}}</em><button v-if="invitation.status==='pending'" @click="revoke(invitation)">Revoke</button></article></div>
    </section>
  </template>
</section></div></template>
